 float[] a2 = {1.0f, 2.0f};
 float[] b2 = {3.0f, 4.0f};
 float[] c2 = {5.0f, 6.0f};
 float[] r2 = Arrays.zip(a2, b2, c2, 0, 0, 0, (x, y, z) -> x + y + z);
 // r2: {9.0, 12.0}

 // Edge: all null - result is empty
